const input = $input.first();
if (!input || !input.json || !input.json.text) {
  return [];
}
const raw = input.json.text;

let start = raw.indexOf('##JSON-START##');
let jsonSlice;

if (start !== -1) {
  start += '##JSON-START##'.length;
  const end = raw.indexOf('##JSON-END##');
  jsonSlice = raw.slice(start, end !== -1 ? end : undefined).trim();
} else {
  // Fallback: marker malformed or missing — locate the JSON array directly
  const arrayStart = raw.indexOf('[');
  const arrayEnd = raw.lastIndexOf(']');
  if (arrayStart === -1 || arrayEnd === -1) {
    throw new Error('Could not locate JSON array in LLM output — markers missing and no array found.');
  }
  jsonSlice = raw.slice(arrayStart, arrayEnd + 1).trim();
}

const findings = JSON.parse(jsonSlice);
const runId = new Date().toISOString();
const projectId = $('Project Found').first().json.project_name;
return findings.map(finding => ({
  json: {
    run_id: runId,
    project_id: projectId,
    type: finding.type,
    title: finding.title,
    description: finding.description,
    evidence_sources: finding.evidence_sources,
    suggested_action: finding.suggested_action,
    status: 'pending'
  }
}));

const findings = $input.all().map(item => item.json);

const grouped = { align: [], capture: [], alert: [] };
findings.forEach(f => {
  if (grouped[f.type]) grouped[f.type].push(f.title);
});

const total = findings.length;
const runId = findings.length > 0 ? findings[0].run_id : 'unknown';

const emojiMap = { align: '🔴', capture: '🟡', alert: '🔵' };
const labelMap = { align: 'Align', capture: 'Capture', alert: 'Alert' };

let summaryText;
let buttons;

if (total === 0) {
  summaryText = `✅ Project Continuity Check — no new findings this run. Everything's in sync.`;
  buttons = [];
} else {
  summaryText = `🤖 Project Continuity Check — ${total} findings\n\n`;

  ['align', 'capture', 'alert'].forEach(type => {
    if (grouped[type].length > 0) {
      summaryText += `${emojiMap[type]} ${labelMap[type]} (${grouped[type].length})\n`;
      grouped[type].forEach(title => {
        summaryText += `• ${title}\n`;
      });
      summaryText += `\n`;
    }
  });

  summaryText = summaryText.trim();

  buttons = [
  { text: '👀 Preview', callback_data: `preview_run:${runId}` },
  { text: '🗑️ Dismiss', callback_data: `dismiss_run:${runId}` }
];
}

return [{
  json: {
    run_id: runId,
    total: total,
    summary_text: summaryText,
    buttons: buttons
  }
}];

const findings = $input.all().map(item => item.json);

const typeLabel = { align: '🔴 Align', capture: '🟡 Capture', alert: '🔵 Alert' };

return findings.map(finding => {
  const cardText = `${typeLabel[finding.type] || finding.type}\n\n` +
    `${finding.title}\n\n` +
    `${finding.description}\n\n` +
