  return {
    json: {
      finding_id: finding.id,
      card_text: cardText,
      buttons: [
        { text: '✅ Approve', callback_data: `approve_finding:${finding.id}` },
        { text: '✏️ Edit', callback_data: `revise_finding:${finding.id}` }
