const data = $input.first().json;
const f = data.suggested_action.fields;

const fields = {};
if (f.description) {
  fields.description = {
    type: "doc",
    version: 1,
    content: [{ type: "paragraph", content: [{ type: "text", text: f.description }] }]
  };
