const text = $json.message.text;
const projectName = text.replace(/^\/continuitycheck\s*/i, '').trim();
return [{ json: { ...$json, requestedProject: projectName } }];

const results = $input.all();
const MIN_SIMILARITY = 0.5;
const MIN_RANK = 0.01;
const MAX_CHUNKS = 10;
const MAX_PER_SOURCE = 4;
const MAX_CHUNK_LENGTH = 1500;
const scored = results.map(item => {
  const isVector = item.json.similarity !== undefined;
  return {
    ...item.json,
    score: isVector ? item.json.similarity : item.json.rank,
    threshold: isVector ? MIN_SIMILARITY : MIN_RANK
  };
});
const sourceCounts = {};
const relevant = [];
for (const r of scored.sort((a, b) => b.score - a.score)) {
  if (r.score === undefined || r.score < r.threshold) continue;
  const count = sourceCounts[r.source_reference] || 0;
  if (count >= MAX_PER_SOURCE) continue;
  relevant.push(r);
  sourceCounts[r.source_reference] = count + 1;
  if (relevant.length >= MAX_CHUNKS) break;
}
if (relevant.length === 0) {
  return [{ json: { priorContextText: "" } }];
}
let formatted = "=== PRIOR CONTEXT ===\n\n";
for (const r of relevant) {
  const text = r.chunk_text.length > MAX_CHUNK_LENGTH
    ? r.chunk_text.slice(0, MAX_CHUNK_LENGTH) + "..."
    : r.chunk_text;
  formatted += `--- From ${r.source_reference} ---\n${text}\n\n`;
}
return [{ json: { priorContextText: formatted } }];

const priorContext = $json.priorContextText;
const currentEvidence = $('Combine Evidence').item.json.combined;

const finalText = currentEvidence + "\n\n" + priorContext;

return [{ json: { combined: finalText } }];

const text = $('Combine Evidence').item.json.combined;
const stopwords = new Set(['this','that','with','from','have','been','were','will','would',
  'their','which','about','these','those','after','before','while','there','where','when',
  'what','than','then','also','into','more','some','such','only','over','under','across',
  'among','between','during','following','since','still','upon','within','without','each',
  'both','every','other','another','same','different']);
// Ticket keys, e.g. KAN-11
const ticketKeys = [...new Set(text.match(/\b[A-Z]{2,}-\d+\b/g) || [])];
// Multi-word proper-noun phrases, e.g. "Asset Accounting", "Data Mapping Tracker"
const properPhrases = [...new Set(text.match(/\b[A-Z][a-z]+(?:\s+[A-Z][a-z]+){1,3}\b/g) || [])];
// Frequently-repeated significant words
const words = text.toLowerCase().match(/\b[a-z]{4,}\b/g) || [];
const freq = {};
for (const w of words) {
  if (stopwords.has(w)) continue;
  freq[w] = (freq[w] || 0) + 1;
}
const topWords = Object.entries(freq)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 20)
  .map(([w]) => w);
const searchTerms = [...ticketKeys, ...properPhrases.slice(0, 15), ...topWords]
  .filter((v, i, arr) => arr.indexOf(v) === i)
  .slice(0, 40)
  .join(' ');
return [{ json: { searchTerms } }];

const fs = require('fs');
const dirPath = '/files/evidence/onedrive';
const files = fs.readdirSync(dirPath);

const results = [];
for (const file of files) {
  const content = fs.readFileSync(`${dirPath}/${file}`, 'utf8');
  results.push({
    json: {
      fileName: file,
      content: content,
      sourceSystem: 'onedrive'
    }
  });
}
return results;

