const originalItems = $('Merge').all();
const lookupResults = $input.all();
const projectId = $('Project Found').first().json.project_name;

// Build a lookup map keyed by source_reference so we never rely on array order/length
const lookupMap = {};
for (const lr of lookupResults) {
  const ref = lr.json.source_reference;
  if (ref) lookupMap[ref] = lr.json;
}

const results = [];
for (const item of originalItems) {
  const fileName = item.json.fileName;
  const content = item.json.content;
  const contentHash = item.json.contentHash;
  const sourceSystem = item.json.sourceSystem;
  const lookupResult = lookupMap[fileName] || {};
  const existingHash = lookupResult.content_hash;
  const isNew = !existingHash || existingHash !== contentHash;
  const hasExistingRecord = !!existingHash;
  results.push({
    json: { fileName, content, contentHash, sourceSystem, isNew, hasExistingRecord, projectId }
  });
}
return results;

const items = $input.all();

let output = '';

for (const item of items) {
  const source = item.json.sourceSystem;
  const label = source === 'onedrive' ? 'DOCUMENT' 
              : source === 'outlook' ? 'EMAIL' 
              : 'JIRA TICKET';
  output += `\n=== ${label}: ${item.json.fileName} ===\n${item.json.content}\n`;
}

return [{ json: { combined: output } }];

const CHUNK_SIZE = 300;
const CHUNK_OVERLAP = 50;
const results = [];
for (const item of $input.all()) {
  const { fileName, content, contentHash, sourceSystem, projectId } = item.json;
  const words = content.split(/\s+/).filter(Boolean);
  if (words.length <= CHUNK_SIZE) {
    results.push({ json: { fileName, sourceSystem, contentHash, projectId, chunkText: content, chunkIndex: 0 } });
    continue;
  }
  let start = 0;
  let chunkIndex = 0;
  while (start < words.length) {
    const end = Math.min(start + CHUNK_SIZE, words.length);
    const chunkText = words.slice(start, end).join(' ');
    results.push({ json: { fileName, sourceSystem, contentHash, projectId, chunkText, chunkIndex } });
    if (end === words.length) break;
    start += CHUNK_SIZE - CHUNK_OVERLAP;
    chunkIndex++;
  }
}
return results;

const results = [];
for (const item of $input.all()) {
  const { sourceSystem, isNew } = item.json;

  if (sourceSystem === 'jira') {
    results.push(item);
    continue;
  }

  if (isNew) {
    results.push(item);
  }
}
return results;

